# ---------------------------------------------------------------------------
# Protection layer (highest priority)
# ---------------------------------------------------------------------------


def is_protected_path(path: Path, *, root: Optional[Path] = None) -> bool:
    """Return True if the path must never be scanned, read, modified, renamed,
    backed up or restored over.

    This is the highest-priority safety gate. It protects:
    - The running script itself
    - All configuration files used by the tool
    - Generated reports
    - Log files
    - Backup directories and their contents
    - Well-known VCS / IDE / virtual-env / build directories
    - Symbolic links (always treated as protected)

    Args:
        path: Absolute or relative path to inspect.
        root: Optional repository root. When supplied, relative path
              calculations are performed against it for more precise matching.

    Returns:
        True when the path is protected and must be left untouched.
    """
    try:
        resolved = path.resolve()
    except (OSError, RuntimeError):
        return True

    # Symbolic links are never touched
    if path.is_symlink() or resolved.is_symlink():
        return True

    name = resolved.name

    # Exact protected file names
    if name in PROTECTED_FILES:
        return True

    # Any path component that is a protected directory name
    for part in resolved.parts:
        if part in PROTECTED_DIRS:
            return True

    # Extra safety: if root is known, also check the relative path string
    if root is not None:
        try:
            rel = resolved.relative_to(root.resolve())
            for part in rel.parts:
                if part in PROTECTED_DIRS:
                    return True
            if rel.name in PROTECTED_FILES:
                return True
        except ValueError:
            pass

    return False


# ---------------------------------------------------------------------------
# Color support (ANSI, no external dependencies)
# ---------------------------------------------------------------------------


class Color(Enum):
    """ANSI color codes for console output."""

    RESET = "\033[0m"
    BOLD = "\033[1m"
    RED = "\033[91m"
    GREEN = "\033[92m"
    YELLOW = "\033[93m"
    BLUE = "\033[94m"
    MAGENTA = "\033[95m"
    CYAN = "\033[96m"
    WHITE = "\033[97m"
    GRAY = "\033[90m"


def colorize(text: str, color: Color, *, enabled: bool = True) -> str:
    """Apply ANSI color to text if enabled and stdout is a TTY.

    Args:
        text: The text to colorize.
        color: The Color enum value.
        enabled: Whether coloring is active.

    Returns:
        Colored or plain text.
    """
    if not enabled or not sys.stdout.isatty():
        return text
    return f"{color.value}{text}{Color.RESET.value}"


# ---------------------------------------------------------------------------
# Progress bar (pure Python)
# ---------------------------------------------------------------------------


class ProgressBar:
    """Simple terminal progress bar without external dependencies."""

    def __init__(
        self,
        total: int,
        *,
        width: int = 40,
        prefix: str = "Progress",
        enabled: bool = True,
    ) -> None:
        """Initialize the progress bar.

        Args:
            total: Total number of steps.
            width: Width of the bar in characters.
            prefix: Text shown before the bar.
            enabled: Whether to display the bar.
        """
        self.total = max(total, 1)
        self.width = width
        self.prefix = prefix
        self.enabled = enabled and sys.stdout.isatty()
        self.current = 0
        self._start = time.perf_counter()

    def update(self, n: int = 1) -> None:
        """Advance the progress bar by n steps.

        Args:
            n: Number of steps to advance.
        """
        self.current = min(self.current + n, self.total)
        if self.enabled:
            self._render()

    def finish(self) -> None:
        """Complete the progress bar and move to the next line."""
        self.current = self.total
        if self.enabled:
            self._render()
            sys.stdout.write("\n")
            sys.stdout.flush()

    def _render(self) -> None:
        """Render the current state of the progress bar."""
        ratio = self.current / self.total
        filled = int(self.width * ratio)
        bar = "█" * filled + "░" * (self.width - filled)
        percent = ratio * 100
        elapsed = time.perf_counter() - self._start
        line = (
            f"\r{self.prefix} |{bar}| "
            f"{self.current}/{self.total} "
            f"({percent:5.1f}%) "
            f"[{elapsed:5.1f}s]"
        )
        sys.stdout.write(line)
        sys.stdout.flush()


